"""Ledger parsing, aggregation, filtering and formatting."""

from __future__ import annotations

import datetime
import re
from dataclasses import dataclass
from decimal import MAX_EMAX, MAX_PREC, MIN_EMIN, Context, Decimal
from typing import Dict, Iterable, List, Optional

_DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}", re.ASCII)
_AMOUNT_RE = re.compile(r"[+-]?\d+(\.\d{1,2})?", re.ASCII)
_SEPARATOR_RE = re.compile(r"[ \t]+")
_LINE_END_RE = re.compile(r"\r\n|\r|\n")

_CENT = Decimal("0.01")
# Exact arithmetic: sums and quantize never round, whatever the amount's size.
# (Addition and quantize are exact operations, so the huge precision costs nothing.)
_WIDE_CONTEXT = Context(prec=MAX_PREC, Emax=MAX_EMAX, Emin=MIN_EMIN)
_ZERO = Decimal("0")


class ParseError(ValueError):
    """A line of the ledger is not valid. ``line`` is its number, counting from 1."""

    def __init__(self, message: str, line: int) -> None:
        super().__init__("line %d: %s" % (line, message))
        self.line = line
        self.reason = message


@dataclass(frozen=True)
class Entry:
    date: datetime.date
    category: str
    amount: Decimal
    note: str = ""


def parse_line(raw: str, line: int) -> Optional[Entry]:
    """Parse one ledger line; return None for blank and comment lines."""
    text = raw.strip()
    if not text or text.startswith("#"):
        return None
    fields = _SEPARATOR_RE.split(text, maxsplit=3)
    if len(fields) < 3:
        raise ParseError(
            "expected DATE CATEGORY AMOUNT [NOTE], got %r" % text, line
        )
    date_text, category, amount_text = fields[0], fields[1], fields[2]
    note = fields[3].strip() if len(fields) > 3 else ""

    if not _DATE_RE.fullmatch(date_text):
        raise ParseError("invalid date %r (expected YYYY-MM-DD)" % date_text, line)
    try:
        date = datetime.date(
            int(date_text[0:4]), int(date_text[5:7]), int(date_text[8:10])
        )
    except ValueError:
        raise ParseError("date does not exist: %s" % date_text, line) from None
    if not _AMOUNT_RE.fullmatch(amount_text):
        raise ParseError(
            "invalid amount %r (expected a number with at most 2 decimals)"
            % amount_text,
            line,
        )
    return Entry(date, category.lower(), Decimal(amount_text), note)


def split_lines(text: str) -> List[str]:
    """Split text on real line endings only: ``\\n``, ``\\r\\n`` and a lone ``\\r``.

    Unlike ``str.splitlines`` this leaves form feed, vertical tab, the
    ``\\x1c``-``\\x1e`` separators, ``\\x85``, U+2028 and U+2029 inside the line.
    A final line ending does not start another line. Terminators are matched
    left to right, so ``\\r\\r\\n`` is two line endings (``\\r``, then ``\\r\\n``).
    """
    lines = _LINE_END_RE.split(text)
    if lines and lines[-1] == "":
        lines.pop()
    return lines


def parse(text: str) -> List[Entry]:
    """Parse ledger text into entries, in file order."""
    if text.startswith("﻿"):
        text = text[1:]  # a single leading BOM, as the CLI's utf-8-sig does
    entries = []
    for number, raw in enumerate(split_lines(text), start=1):
        entry = parse_line(raw, number)
        if entry is not None:
            entries.append(entry)
    return entries


def balance(entries: Iterable[Entry]) -> Decimal:
    total = _ZERO
    for e in entries:
        total = _WIDE_CONTEXT.add(total, e.amount)
    return total


def by_category(entries: Iterable[Entry]) -> Dict[str, Decimal]:
    totals = {}  # type: Dict[str, Decimal]
    for e in entries:
        totals[e.category] = _WIDE_CONTEXT.add(
            totals.get(e.category, _ZERO), e.amount
        )
    return {key: totals[key] for key in sorted(totals)}


def month_key(date: datetime.date) -> str:
    return "%04d-%02d" % (date.year, date.month)


def by_month(entries: Iterable[Entry]) -> Dict[str, Decimal]:
    totals = {}  # type: Dict[str, Decimal]
    for e in entries:
        key = month_key(e.date)
        totals[key] = _WIDE_CONTEXT.add(totals.get(key, _ZERO), e.amount)
    return {key: totals[key] for key in sorted(totals)}


def filter_entries(
    entries: Iterable[Entry],
    category: Optional[str] = None,
    since: Optional[datetime.date] = None,
    until: Optional[datetime.date] = None,
) -> List[Entry]:
    wanted = category.lower() if category is not None else None
    result = []
    for e in entries:
        if wanted is not None and e.category != wanted:
            continue
        if since is not None and e.date < since:
            continue
        if until is not None and e.date > until:
            continue
        result.append(e)
    return result


def format_money(amount: Decimal) -> str:
    """Amount with exactly 2 decimals; negative zero shows as 0.00."""
    q = amount.quantize(_CENT, context=_WIDE_CONTEXT)
    if q == 0:
        q = abs(q)
    return "{:f}".format(q)


def format_entry(entry: Entry) -> str:
    line = "%s %s %s" % (
        entry.date.isoformat(),
        entry.category,
        format_money(entry.amount),
    )
    if entry.note:
        line += " " + entry.note
    return line
